#include "/home/reinsirk/Atcoder_Env/Verify/current/common/fast_io.hpp"
#include <algorithm>
#include <cstdint>
#include <limits>
#include <vector>
#include <utility>
struct Line { std::int64_t a{}, b{}; std::int64_t operator()(std::int64_t x) const { return a*x+b; } };
struct Op { int t; std::int64_t a,b; };
struct Reference {
    std::vector<std::int64_t> xs;
    std::vector<Line> lines;
    std::vector<unsigned char> used;
    explicit Reference(std::vector<std::int64_t> x):xs(std::move(x)),lines(4*xs.size()),used(4*xs.size()){}
    void add(Line line,std::size_t node,std::size_t l,std::size_t r) {
        if (!used[node]) { lines[node]=line; used[node]=1; return; }
        const std::size_t m=(l+r)/2;
        if (line(xs[m])<lines[node](xs[m]))std::swap(line,lines[node]);
        if (r-l==1)return;
        if(line(xs[l])<lines[node](xs[l]))add(line,2*node,l,m);
        else if(line(xs[r-1])<lines[node](xs[r-1]))add(line,2*node+1,m,r);
    }
    std::int64_t query(std::size_t index)const {
        std::int64_t answer=std::numeric_limits<std::int64_t>::max();
        std::size_t node=1,l=0,r=xs.size();
        while(true){if(used[node])answer=std::min(answer,lines[node](xs[index]));if(r-l==1)return answer;const auto m=(l+r)/2;if(index<m){node*=2;r=m;}else{node=2*node+1;l=m;}}
    }
};
int main(){
 int n{},q{};if(!(verify_in>>n>>q))return 0;
 std::vector<Line> initial(n);for(auto&line:initial)verify_in>>line.a>>line.b;
 std::vector<Op> operations(q);std::vector<std::int64_t> xs;
 for(auto&op:operations){verify_in>>op.t>>op.a;if(op.t==0)verify_in>>op.b;else xs.push_back(op.a);}
 if(xs.empty())return 0;
 std::sort(xs.begin(),xs.end());xs.erase(std::unique(xs.begin(),xs.end()),xs.end());Reference ref(std::move(xs));
 for(auto line:initial)ref.add(line,1,0,ref.xs.size());
 for(auto op:operations)if(op.t==0)ref.add({op.a,op.b},1,0,ref.xs.size());else verify_out<<ref.query(std::lower_bound(ref.xs.begin(),ref.xs.end(),op.a)-ref.xs.begin())<<'\n';
}
